const items = $input.all();
const issues = [];
const now = new Date();
for (const item of items) {
  const appt = item.json;
  const status = (appt['Status'] || '').toString().trim();
  if (status !== 'Scheduled') continue;
  const dateStr = (appt['Appt Date'] || '').toString().trim();
  const timeStr = (appt['Appt Time'] || '').toString().trim();
  const dateMatch = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const timeMatch = timeStr.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  if (!dateMatch || !timeMatch) continue;
  const year = parseInt(dateMatch[1], 10);
  const month = parseInt(dateMatch[2], 10);
  const day = parseInt(dateMatch[3], 10);
  let hour = parseInt(timeMatch[1], 10);
  const minute = parseInt(timeMatch[2], 10);
  const ampm = timeMatch[3].toUpperCase();
  if (ampm === 'PM' && hour !== 12) hour += 12;
  if (ampm === 'AM' && hour === 12) hour = 0;
  const apptDateTime = new Date(Date.UTC(year, month - 1, day, hour + 5, minute));
  const hoursUntil = (apptDateTime.getTime() - now.getTime()) / (1000 * 60 * 60);
  if (hoursUntil < 0) continue;
  const reminder24Sent = (appt['Reminder 24h'] || '').toString().trim().length > 0;
  const reminder2Sent = (appt['Reminder 2h'] || '').toString().trim().length > 0;
  const name = appt['Customer Name'] || 'An appointment';
  const id = appt['Appt ID'] || '(no ID)';
  if (!reminder24Sent && hoursUntil >= 20 && hoursUntil <= 26) {
    issues.push({ json: {
      checkType: 'appointment_reminder', apptId: id, customerName: name, reminderType: '24-hour',
      hoursUntil: Math.round(hoursUntil * 10) / 10,
      detail: name + ' (' + id + ') is ~' + Math.round(hoursUntil) + 'h out and still missing its 24h reminder'
    }});
  }
  if (!reminder2Sent && hoursUntil >= 1 && hoursUntil <= 2) {
    issues.push({ json: {
      checkType: 'appointment_reminder', apptId: id, customerName: name, reminderType: '2-hour',
      hoursUntil: Math.round(hoursUntil * 10) / 10,
      detail: name + ' (' + id + ') is ~' + Math.round(hoursUntil) + 'h out and still missing its 2h reminder'
    }});
  }
}
return issues;

const items = $input.all();
const issues = [];
const now = new Date();
const thresholds = { 0: 24, 1: 72, 2: 96 };
const dayLabel = { 0: 1, 1: 3, 2: 7 };
const BUFFER_HOURS = 30;
for (const item of items) {
  const lead = item.json;
  const status = (lead['Status'] || '').toString().trim();
  if (status !== 'New' && status !== 'Contacted') continue;
  const countRaw = parseInt(lead['Follow-up Count'], 10);
  const count = isNaN(countRaw) ? 0 : countRaw;
  if (count >= 3) continue;
  const lastTouchRaw = (lead['Last Contact'] || lead['Date Created'] || '').toString().trim();
  let hoursSince = 9999;
  if (lastTouchRaw) {
    const parsed = new Date(lastTouchRaw);
    if (!isNaN(parsed.getTime())) {
      hoursSince = (now.getTime() - parsed.getTime()) / (1000 * 60 * 60);
    }
  }
  const threshold = thresholds[count];
  if (hoursSince >= threshold + BUFFER_HOURS) {
    const name = ((lead['First Name'] || '') + ' ' + (lead['Last Name'] || '')).trim() || 'A lead';
    const id = lead['Lead ID'] || '(no ID)';
    const overdueBy = Math.round(hoursSince - threshold);
    issues.push({ json: {
      checkType: 'follow_up', leadId: id, customerName: name, followUpCount: count,
      hoursOverdue: overdueBy,
      detail: name + ' (' + id + ') looks ~' + overdueBy + 'h overdue for its Day-' + dayLabel[count] + ' follow-up'
    }});
  }
}
return issues;

const items = $input.all();
if (items.length === 0) {
  return [];
}
const lines = items.map(function (item, idx) { return (idx + 1) + '. ' + item.json.detail; });
const message = 'Valfin System Health Alert\n\n' +
  items.length + ' issue(s) detected that may indicate a scheduled workflow did not run as expected:\n\n' +
  lines.join('\n') +
  '\n\nCheck n8n executions for Workflow 09 (Appointment Reminders) and/or Workflow 05 (Follow-Up Sequence). ' +
  'This is an automated freshness check, not a guarantee something is broken -- verify in the CRM before assuming the worst.';
return [{ json: { issueCount: items.length, alertMessage: message } }];
